const importadores = $('Obtener Importadores').all().map(i => i.json);
const declaraciones = $('Obtener Declaraciones').all().map(i => i.json);
const detalles = $('Obtener Detalles').all().map(i => i.json);
const paises = $('Obtener Paises').all().map(i => i.json);

const paisMap = new Map(paises.map(p => [p.id_pais, p.nombre]));
const decMap = new Map(declaraciones.map(d => [d.id_declaracion, d.id_importador]));

const totales = new Map();
const duasVistos = new Map();

for (const det of detalles) {
  const idImp = decMap.get(det.id_declaracion);
  if (!idImp) continue;
  const valorLinea = Number(det.cantidad) * Number(det.valor_unitario);
  totales.set(idImp, (totales.get(idImp) || 0) + valorLinea);

  if (!duasVistos.has(idImp)) duasVistos.set(idImp, new Set());
  duasVistos.get(idImp).add(det.id_declaracion);
}

const lista = [];
for (const imp of importadores) {
  const total = Math.round((totales.get(imp.id_importador) || 0) * 100) / 100;
  const cantDuas = duasVistos.has(imp.id_importador) ? duasVistos.get(imp.id_importador).size : 0;
  lista.push({
    identificacion_tributaria: imp.identificacion_tributaria,
    razon_social: imp.razon_social,
    pais_importador: paisMap.get(imp.id_pais) || 'Desconocido',
    total_valor_declarado_usd: total,
    total_declaraciones_tramitadas: cantDuas,
    moneda: 'USD'
  });
}

lista.sort((a, b) => b.total_valor_declarado_usd - a.total_valor_declarado_usd || a.razon_social.localeCompare(b.razon_social));

let currentRank = 0;
let prevTotal = null;
const ranked = [];
for (const item of lista) {
  if (item.total_valor_declarado_usd !== prevTotal) {
    currentRank++;
    prevTotal = item.total_valor_declarado_usd;
  }
  if (currentRank === 1) {
    ranked.push({ ranking_valor: 1, ...item });
  }
}

return [{
  json: {
    estado: 'exitoso',
    herramienta: 'consultar_importador_mayor_valor',
    criterio: 'Mayor valor acumulado declarado en USD (DENSE_RANK = 1)',
    total_registros: ranked.length,
    es_parcial: false,
    datos: ranked
  }
}];
